selector_to_html = {"a[href=\"install.html#running-tests\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Running tests<a class=\"headerlink\" href=\"#running-tests\" title=\"Link to this heading\">#</a></h2><p>After installation, you can generally run the following tests. For specific backend support tests, please refer to .github/workflow/${backend_name}-build-and-test.yml in the corresponding branch.</p>", "a[href=\"#getting-started\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Getting Started<a class=\"headerlink\" href=\"#getting-started\" title=\"Link to this heading\">#</a></h1><p>This section covers the requirements for installing and running FlagTree and guides you through installing FlagTree.</p>", "a[href=\"requirements.html#backend-integrations\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Backend integrations<a class=\"headerlink\" href=\"#backend-integrations\" title=\"Link to this heading\">#</a></h2><p>The following backends have been integrated into FlagTree. For new vendors, you can refer to the following code links for your integrations:</p>", "a[href=\"install.html#option-2-install-from-source\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Option 2: Install from source<a class=\"headerlink\" href=\"#option-2-install-from-source\" title=\"Link to this heading\">#</a></h2><p>For installing FlagTree on different backends from source, see the following list:</p>", "a[href=\"install.html#q-a\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Q&amp;A<a class=\"headerlink\" href=\"#q-a\" title=\"Link to this heading\">#</a></h2><p>Q: After installation, running the program reports: version GLIBC or GLIBCXX not found</p><p>A: Check which GLIBC / GLIBCXX versions are supported by libc.so.6 and libstdc++.so.6.0.30 in your environment:</p>", "a[href=\"install.html#option-1-install-from-prebuilt-docker-image\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Option 1: Install from prebuilt Docker image<a class=\"headerlink\" href=\"#option-1-install-from-prebuilt-docker-image\" title=\"Link to this heading\">#</a></h2><p>For installing FlagTree on different backends from prebuilt Docker image, see the following list:</p>", "a[href=\"requirements.html#system-software-requirements\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">System software requirements<a class=\"headerlink\" href=\"#system-software-requirements\" title=\"Link to this heading\">#</a></h2><p>You may need the following system softwares:</p>", "a[href=\"install.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Install FlagTree<a class=\"headerlink\" href=\"#install-flagtree\" title=\"Link to this heading\">#</a></h1><h2>Option 1: Install from prebuilt Docker image<a class=\"headerlink\" href=\"#option-1-install-from-prebuilt-docker-image\" title=\"Link to this heading\">#</a></h2><p>For installing FlagTree on different backends from prebuilt Docker image, see the following list:</p>", "a[href=\"install.html#option-3-install-wheel-package\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Option 3: Install wheel package<a class=\"headerlink\" href=\"#option-3-install-wheel-package\" title=\"Link to this heading\">#</a></h2><p>If you do not wish to build from source, you can directly pull and install whl (partial backend support).</p>", "a[href=\"requirements.html#backends-triton-versions-and-branches\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Backends, Triton versions, and branches<a class=\"headerlink\" href=\"#backends-triton-versions-and-branches\" title=\"Link to this heading\">#</a></h2><p>Each backend is based on different versions of Triton, and therefore resides in different protected branches. All these protected branches have equal status. CI/CD runners are provisioned for every backend listed in the table.</p>", "a[href=\"requirements.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Requirements<a class=\"headerlink\" href=\"#requirements\" title=\"Link to this heading\">#</a></h1><p>This section includes requirements about using FlagTree, including supported platforms and dependencies. FlagTree can be successfully installed and run only when all requirements are met.</p>", "a[href=\"requirements.html#features-on-different-branches\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Features on different branches<a class=\"headerlink\" href=\"#features-on-different-branches\" title=\"Link to this heading\">#</a></h2><p>FlagTree\u2019s extension components are currently available on some backends:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
